package com.foodbridge.consumer;
import com.foodbridge.orders.PurchaseOrderRepository;import jakarta.validation.constraints.*;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;
@Controller public class ProfileController {private final ConsumerProfileRepository profiles;private final PurchaseOrderRepository orders;public ProfileController(ConsumerProfileRepository p,PurchaseOrderRepository o){profiles=p;orders=o;}
    @GetMapping("/consumer/profile") public String profile(Authentication auth,Model model){ConsumerProfile p=profiles.findByEmail(auth.getName()).orElseGet(()->profiles.save(new ConsumerProfile(auth.getName(),"","","")));model.addAttribute("profile",p);model.addAttribute("form",new ProfileForm(p.getFullName(),p.getPhone(),p.getPreferredPickupArea()));model.addAttribute("orderCount",orders.findByConsumerEmailOrderByCreatedAtDesc(auth.getName()).size());return "consumer/profile";}
    @PostMapping("/consumer/profile") public String update(Authentication auth,@ModelAttribute("form") ProfileForm form,BindingResult errors,Model model){if(form.fullName==null||form.fullName.isBlank())errors.rejectValue("fullName","required","Name is required.");if(errors.hasErrors()){model.addAttribute("profile",profiles.findByEmail(auth.getName()).orElseThrow());model.addAttribute("orderCount",orders.findByConsumerEmailOrderByCreatedAtDesc(auth.getName()).size());return "consumer/profile";}ConsumerProfile p=profiles.findByEmail(auth.getName()).orElseThrow();p.update(form.fullName,form.phone,form.preferredPickupArea);profiles.save(p);return "redirect:/consumer/profile?saved";}
    public static class ProfileForm{public String fullName;public String phone;public String preferredPickupArea;public ProfileForm(){}public ProfileForm(String n,String p,String a){fullName=n;phone=p;preferredPickupArea=a;}public String getFullName(){return fullName;}public void setFullName(String s){fullName=s;}public String getPhone(){return phone;}public void setPhone(String s){phone=s;}public String getPreferredPickupArea(){return preferredPickupArea;}public void setPreferredPickupArea(String s){preferredPickupArea=s;}}
}
